import React, { useRef, useState } from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";
import { apiRunVirulenceTool } from "../service/virulence";
import { apiRunAmrTool } from "../service/amr";
import { useNotice } from "../context/NoticeContext";
import LoadingSpinner from "../components/LoadingSpinner";
import ResultComponent from "../components/ResultComponent";

const Container = styled.div`
  margin-top: 10px;
  display: flex;
  justify-content: center;
`;

const Wrapper = styled.div`
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const Title = styled.h2`
  margin-bottom: 20px;
  text-align: center;
  font-size: 70px;
  font-weight: bold;
  color: #1e3a8a;
`;

const DropdownWrapper = styled.div`
  margin-top: 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  width: 100%;
  align-items: center;
`;

const ChooseFileButtonWrapper = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  gap: 15px;
`;

const ChooseFileButton = styled.label`
  padding: 25px 50px;
  background-color: #ffffff;
  color: #007bff;
  border-radius: 8px;
  cursor: pointer;
  font-size: 50px;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  text-align: center;
  width: 80%;
  height: 500px;
  transition: background-color 0.3s ease, color 0.3s ease; 
  border: 2px dashed #007bff;
  margin: 0 auto;

  &:hover {
    background-color: #e2f1ff; 
    color: #0056b3; 
    transform: translateY(-3px); 
  }

  input {
    display: none;
  }
`;

const FileName = styled.p`
  font-size: 18px;
  color: #333;
  margin: 0;
  font-weight: 500;
  text-align: center;
  word-wrap: break-word;
  max-width: 300px;
`;

const FileInfoWrapper = styled.div`
  margin-top: 15px;
  padding: 10px;
  background-color: #f1f1f1;
  border-radius: 5px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
`;

const FileInfoText = styled.p`
  font-size: 16px;
  color: #555;
  margin: 0;
  text-align: center;
  word-wrap: break-word;
`;

const ButtonWrapper = styled.div`
  display: flex;
  justify-content: center;
  gap: 15px;
  margin-top: 20px;
`;

const ButtonSubmit = styled.button`
  padding: 12px 20px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 18px;
  transition: background-color 0.3s;

  &:hover {
    background-color: #0056b3;
  }
`;

const ButtonReset = styled.button`
  padding: 12px 20px;
  background-color: #f8f9fa;
  color: #007bff;
  border: 1px solid #007bff;
  border-radius: 8px;
  cursor: pointer;
  font-size: 18px;
  margin-left: 10px;
  transition: background-color 0.3s;

  &:hover {
    background-color: #e2e6ea;
  }
`;

const Tool = () => {
  const { t } = useTranslation();
  const fileInputRef = useRef(null);
  const [isLoading, setIsLoading] = useState(false);
  const { showNotice } = useNotice();
  const [file, setFile] = useState(null);
  const [fastaInfo, setFastaInfo] = useState({
    name: "Acinetobacter Baumanii",
    header: "",
    length: "",
    createdAt: "",
  });
  const [virulenceInfo, setVirulenceInfo] = useState([]);
  const [amrInfo, setAmrInfo] = useState([]);
  const [isSuccessConfirm, setIsSuccessConfirm] = useState(false);
  const [header, setHeader] = useState("");
  const [length, setLength] = useState(0);

  const handleFileChange = (e) => {
    const uploadedFile = e.target.files[0];
    if (uploadedFile) {
      setFile(uploadedFile);
      const reader = new FileReader();
      reader.onload = function (event) {
        const text = event.target.result;
        const lines = text.split(/\r?\n/);
        const headerLine = lines.find((line) => line.startsWith(">"));
        setHeader(headerLine || "");
        const sequenceLines = lines.filter((line) => !line.startsWith(">") && line.trim() !== "");
        const totalLength = sequenceLines.join("").length;
        setLength(totalLength);
      };
      reader.readAsText(uploadedFile);
    }
  };

  const handleReset = () => {
    setFile(null);
    setHeader("");
    setLength(0);
    setIsSuccessConfirm(false);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!file) {
      showNotice(0, t("toolPage.uploadFile"));
      return;
    }
    setIsLoading(true);
    try {
      const [virulence, amr] = await Promise.all([
        apiRunVirulenceTool(file),
        apiRunAmrTool(file),
      ]);
      setFastaInfo((prev) => ({
        ...prev,
        header,
        length,
        createdAt: Date.now(),
      }));
      setVirulenceInfo(virulence.data);
      setAmrInfo(amr.data);
      showNotice(1, t("toolPage.successConfirm"));
      setIsSuccessConfirm(true);
      setIsLoading(false);
    } catch (error) {
      showNotice(0, t("toolPage.failConfirm"));
    }
  };

  return (
    <Container>
      <Wrapper>
        <Title>{t("toolPage.title")}</Title>
        <DropdownWrapper>
          <ChooseFileButtonWrapper>
            <ChooseFileButton>
            <img src="./upload.png"  alt="Upload Icon" width="40" height="40"/>
              {t("toolPage.chooseFile")}
              <input
                type="file"
                accept=".fa,.fas,.fna,.fasta"
                onChange={handleFileChange}
                ref={fileInputRef}
              />
            </ChooseFileButton>
            {file && <FileName>{file.name}</FileName>}
          </ChooseFileButtonWrapper>
          {file && (
            <FileInfoWrapper>
              <FileInfoText>{t("toolPage.header")}: {header}</FileInfoText>
              <FileInfoText>{t("toolPage.length")}: {length} bp</FileInfoText>
            </FileInfoWrapper>
          )}
        </DropdownWrapper>
        <ButtonWrapper>
          <ButtonSubmit type="button" onClick={handleSubmit}>
            {t("toolPage.submitBtn")}
          </ButtonSubmit>
          <ButtonReset type="button" onClick={handleReset}>
            {t("toolPage.resetBtn")}
          </ButtonReset>
        </ButtonWrapper>
        {isLoading && <LoadingSpinner />}
        {isSuccessConfirm && (
          <ResultComponent
            fastaInfo={fastaInfo}
            virulenceInfo={virulenceInfo}
            amrInfo={amrInfo}
          />
        )}
      </Wrapper>
    </Container>
  );
};

export default Tool;
